from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    def is_paren(char):
        return char in "()"

    def is_open(char):
        return char == '('

    def is_close(char):
        return char == ')'

    def clean_string(s):
        return ''.join(filter(is_paren, s))

    def find_group_start(s):
        stack = []
        for i, char in enumerate(s):
            if is_open(char):
                stack.append(i)
            elif is_close(char):
                if stack:
                    stack.pop()
                    if not stack:
                        return i
        return -1

    def find_group_end(s):
        stack = []
        for i, char in enumerate(s):
            if is_open(char):
                stack.append(i)
            elif is_close(char):
                stack.pop()
                if not stack:
                    return i
        return -1

    # Clean the string to remove spaces
    cleaned_string = clean_string(paren_string)

    # Find the boundaries of each group
    start_indices = [find_group_start(cleaned_string) for _ in range(cleaned_string.count('('))]
    end_indices = [find_group_end(cleaned_string) for _ in range(cleaned_string.count(')'))]

    # Ensure the groups are in order
    indices = list(zip(start_indices, end_indices))
    indices.sort()

    # Extract the groups
    groups = [cleaned_string[start + 1:end] for start, end in indices]

    return groups

